Lemma havocG_go_eq : forall fk sp ub uk z1 bnds t kn infos,
  Forall2 (EINF (mkbc fk) t) kn infos ->
  havocG_go (mkbc fk) sp ub uk (ELit z1) (pt_map (fun g => (g, havoc_verdict sp uk (zlit64 z1) g)) bnds) kn infos
